<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoSubActividad, guardarSubActividad, listarSubActividades } from '../services/subActividades'
import type { CostoOption, SubActividad, SubActividadPayload } from '../interfaces/subActividad.interface'
const rows=ref<SubActividad[]>([]),actividades=ref<CostoOption[]>([]),inductores=ref<CostoOption[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<SubActividadPayload>({nombre:'',descripcion:'',actividad_id:0,inductor_id:0})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarSubActividades(criterio.value,next);rows.value=r.data;actividades.value=r.actividades??[];inductores.value=r.inductores??[];page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:SubActividad){editing.value=item?.id??null;form.nombre=item?.nombre??'';form.descripcion=item?.descripcion??'';form.actividad_id=item?.actividad_id??0;form.inductor_id=item?.inductor_id??0;error.value='';modal.value=true}
async function save(){const nombre=form.nombre.trim(),descripcion=form.descripcion.trim();if(!form.actividad_id||!form.inductor_id)return void(error.value='Debe seleccionar la actividad y el inductor.');if(nombre.length<2||nombre.length>45)return void(error.value='El nombre debe tener entre 2 y 45 caracteres.');if(descripcion.length>100)return void(error.value='La descripción no puede superar los 100 caracteres.');saving.value=true;error.value='';try{await guardarSubActividad(editing.value,{nombre:nombre.toUpperCase(),descripcion:descripcion.toUpperCase(),actividad_id:form.actividad_id,inductor_id:form.inductor_id});modal.value=false;success.value=`Subactividad ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:SubActividad){if(!confirm(`¿Desea ${item.activo?'desactivar':'activar'} la subactividad ${item.nombre}?`))return;try{await cambiarEstadoSubActividad(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page" style="--a:#c65a62"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/parametros-costos">Parámetros de costos</RouterLink> / Subactividades</nav><header class="hero"><div class="mark">SA</div><div><small>MIA · CONTABILIDAD · COSTOS</small><h1>Subactividades</h1><p>Administra tareas específicas y su inductor para la distribución de costos.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva subactividad</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por nombre o descripción"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando subactividades…</div><div v-else-if="!rows.length" class="empty">No se encontraron subactividades.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Nombre</th><th>Descripción</th><th>Actividad</th><th>Inductor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><b>{{item.nombre}}</b></td><td>{{item.descripcion||'—'}}</td><td>{{item.actividad?.nombre||'—'}}</td><td>{{item.inductor?.nombre||'—'}}</td><td><span :class="item.activo?'ok':'bad'">{{item.activo?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">{{item.activo?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>PARÁMETROS DE COSTOS</small><h2>{{editing?'Editar':'Nueva'}} subactividad</h2></div><button type="button" @click="modal=false">×</button></header><label>Actividad *<select v-model.number="form.actividad_id" required><option :value="0">Seleccione</option><option v-for="item in actividades" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Inductor *<select v-model.number="form.inductor_id" required><option :value="0">Seleccione</option><option v-for="item in inductores" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Nombre *<input v-model="form.nombre" required minlength="2" maxlength="45" @input="form.nombre=form.nombre.toUpperCase()"></label><label>Descripción<input v-model="form.descripcion" maxlength="100" @input="form.descripcion=form.descripcion.toUpperCase()"></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped src="./costCrud.css"></style>
